import {migrateChinese} from './locale.js';
import {mountWorkspace} from './workspace.js';
import {sample,analyzeBrief,createDirections,generateCampaign,reviseAsset,refineDirection} from './providers.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let project=null,selected=null,phase=0,busy=false,analysisRun=0;
try{project=JSON.parse(localStorage.getItem('forma-project'))}catch{}
const save=()=>{try{localStorage.setItem('forma-project',JSON.stringify(project))}catch{toast('浏览器存储空间已满，本次仍可继续操作。建议换用较小的图片后再保存。')}};
const toast=t=>{$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)};
function go(path){history.pushState({},'',path);render();window.scrollTo(0,0)}
window.addEventListener('popstate',render);
const path=s=>`/project/${project.id}/${s}`;
function shell(content,step=-1){$('#app').innerHTML=`<header><div class="left"><a class="logo" href="/">forma<i>✳</i></a><span class="tag">创意工作台</span></div><div class="right"><span class="muted" style="font-size:14px">${project?esc(project.brand)+' / '+esc(project.product):'从一点想法，到一整套创意。'}</span><span class="avatar">${project?esc(project.brand.slice(0,2)):'F'}</span></div></header>${step>=0?`<nav class="steps" aria-label="Campaign progress">${['Your brief','Agent analysis','创意方向','推广创作'].map((x,i)=>`<div class="step ${i===step?'active':i<step?'done':''}"><span>${i<step?'✓':i+1}</span>${x}</div>`).join('')}</nav>`:''}<main>${content}</main>`;document.querySelectorAll('a[href^="/"]').forEach(a=>a.onclick=e=>{e.preventDefault();go(a.getAttribute('href'))})}
const title=(ey,h,p,right='')=>`<div class="heading"><div><div class="eyebrow">${ey}</div><h1>${h}</h1><p class="lead">${p}</p></div>${right}</div>`;
let disposeWorkspace=null;
function workspace(){(project.assets||[]).forEach(a=>{const d=project.creativeDirections?.find(d=>d.id===a.context?.direction);if(d)a.context={directionName:d.name,keyMessage:d.keyMessage,visualDirection:d.visualDirection,...a.context}});shell('');disposeWorkspace=mountWorkspace({project,save,esc,analyzeBrief,createDirections,refineDirection,generateCampaign,visual,moodboard,openAsset:id=>go(path('asset/'+id)),download});}
function render(){migrateChinese(project);if(project)save();if(disposeWorkspace){disposeWorkspace();disposeWorkspace=null}document.body.classList.remove('in-workspace');const p=location.pathname;if(p==='/'){landing();return}if(!project){project={id:crypto.randomUUID(),brand:'',product:'',description:'',brandDescription:'',keywords:[],sellingPoints:'',goal:'新品上市',objective:'',audience:'',references:[],images:[]};save()}if(p.includes('/asset/'))assetDetail(p.split('/').pop());else{document.body.classList.add('in-workspace');workspace()}}
function landing(){shell(`<section class="landing"><div><div class="eyebrow">下一次创作，从这里开始</div><h1>让一个想法，<br>长成一整套<br>品牌创意。</h1><p class="lead">从你的产品和推广目标出发，一起找到创意方向，再展开成一套风格统一的素材。</p><div class="row"><button class="primary" id="new">开始创作 <span aria-hidden="true">↗</span></button><button class="text" id="sample">体验 NOMA 示例 →</button></div><p class="demo-note">创意搭档 · 演示版 0.2</p></div><div class="landing-art"><img src="/assets/a.png" alt="自然光下的 NOMA 便携咖啡机"><div class="art-caption"><div><div class="eyebrow" style="margin-bottom:6px">NOMA / 新品上市推广</div><h3>你的咖啡时刻，不限地点。</h3></div><span>↗</span></div></div></section><div class="landing-foot"><span>01 &nbsp; 聊聊需求</span><span>02 &nbsp; 找到方向</span><span>03 &nbsp; 展开创意</span></div>${project?`<div class="agent-note"><span class="spark">↳</span><div>上次的创作：<strong>${esc(project.brand)}</strong></div><button class="text" id="resume" style="margin-left:auto">继续创作 →</button></div>`:''}`);$('#new').onclick=()=>{location.href='/studio'};$('#sample').onclick=()=>{project=structuredClone(sample);project.id=crypto.randomUUID();save();go('/project/new')};if($('#resume'))$('#resume').onclick=()=>go(path(project.assets?.length?'campaign':project.creativeDirections?'directions':project.brief?'analysis':'analysis'))}
const field=(label,name,value='',type='input')=>`<label class="field">${label}${type==='textarea'?`<textarea name="${name}">${esc(value)}</textarea>`:`<input name="${name}" value="${esc(value)}" ${['product','brand'].includes(name)?'required':''}>`}</label>`;
function brief(){if(!project){project={...structuredClone(sample),id:crypto.randomUUID()}}shell(title('01 / Context','A little context goes a long way.','Tell us what you’re making, who it’s for, and what you want to achieve.',`<button id="fill">Use NOMA sample</button>`)+`<form id="brief-form" class="form-layout"><div><section class="panel"><h2>01 &nbsp; The product</h2><div class="fields">${field('Product name','product',project.product)}${field('Target audience','audience',project.audience)}</div>${field('Product description','description',project.description,'textarea')}${field('Key selling points · one per line','sellingPoints',project.sellingPoints,'textarea')}<label class="field upload">Product images <span class="muted">Add up to 4 images · JPG, PNG, WebP · 5 MB each</span><input type="file" id="product-images" accept="image/jpeg,image/png,image/webp" multiple></label><div class="previews" id="product-preview">${(project.images||[]).map(x=>`<img src="${esc(x)}" alt="Uploaded product">`).join('')}</div></section><section class="panel"><h2>02 &nbsp; The brand</h2>${field('Brand name','brand',project.brand)}${field('A few words about your brand','brandDescription',project.brandDescription,'textarea')}<div class="field">Brand keywords<div class="chips" id="keywords">${['简约','有趣','高级','自然','年轻','都市','温暖','独立'].map(x=>`<button type="button" data-keyword="${x}" class="${project.keywords?.includes(x)?'lime':''}">${x}</button>`).join('')}</div></div>${field('Additional brand keywords','customKeywords',project.customKeywords)}</section><section class="panel"><h2>03 &nbsp; The ambition</h2><label class="field">Marketing goal<select name="goal">${['新品上市','Social Campaign','Promotion','Brand Awareness'].map(x=>`<option ${project.goal===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('What are you trying to achieve?','objective',project.objective,'textarea')}</section><section class="panel"><h2>04 &nbsp; Your references</h2><p class="muted" style="font-size:14px;margin-bottom:20px">A competitor, a visual style, or something that feels right.</p><div id="references">${(project.references||[]).map(refRow).join('')}</div><button type="button" id="add-ref">+ Add reference URL</button><br><br><label class="field upload">参考图片s<input id="reference-images" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div class="previews" id="reference-preview">${(project.referenceImages||[]).map(x=>`<img src="${esc(x)}" alt="Uploaded reference">`).join('')}</div>${field('What do you like about these references?','referenceNotes',project.referenceNotes,'textarea')}<p class="demo-note">Demo mode: URLs are saved as context. Website and image analysis are simulated.</p></section><button class="primary" type="submit">Analyze & Create 创意方向 →</button></div><aside class="panel aside"><div class="eyebrow">A creative partner, not a blank canvas</div><h2>Context becomes direction.</h2><p class="muted">We’ll pull your brief together, explore three distinct ideas, and let you choose the one to develop.</p><ol><li>Understand the opportunity</li><li>Find a creative point of view</li><li>Build a connected set of assets</li></ol><div class="demo-note">Your project is saved in this browser. Uploads stay on this device.</div></aside></form>`,0);$('#fill').onclick=()=>{project={...structuredClone(sample),id:project.id};save();brief()};$('#keywords').onclick=e=>{const b=e.target.closest('[data-keyword]');if(b)b.classList.toggle('lime')};$('#add-ref').onclick=()=>$('#references').insertAdjacentHTML('beforeend',refRow(''));$('#references').onclick=e=>{if(e.target.matches('[data-remove]'))e.target.parentElement.remove()};$('#product-images').onchange=e=>upload(e,'images','product-preview');$('#reference-images').onchange=e=>upload(e,'referenceImages','reference-preview');$('#brief-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));project={...project,...data,keywords:[...document.querySelectorAll('[data-keyword].lime')].map(x=>x.dataset.keyword),references:[...document.querySelectorAll('[data-reference]')].map(x=>x.value).filter(Boolean),brief:null,creativeDirections:null,selectedDirection:null,assets:[]};save();go(path('analysis'))}}
const refRow=x=>`<div class="ref-row"><input aria-label="Reference URL" data-reference type="url" placeholder="https://example.com" value="${esc(x)}"><button type="button" data-remove aria-label="Remove reference">×</button></div>`;
async function upload(e,key,preview){const files=[...e.target.files];if(files.length>4||files.some(f=>f.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type))){toast('Choose up to 4 JPG, PNG, or WebP files, under 5 MB each.');e.target.value='';return}project[key]=await Promise.all(files.map(f=>new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(f)})));$('#'+preview).innerHTML=project[key].map(x=>`<img src="${x}" alt="Uploaded image">`).join('');save()}
async function analysis(){const run=++analysisRun;shell(title('02 / 需求理解','Finding the story in your brief.','A shared understanding before we start creating.')+`<div class="analysis-layout"><div id="work">${['Analyzing your product','需求理解 brand positioning','Defining the audience','Reviewing references','Identifying visual opportunities','Building the creative brief'].map((x,i)=>`<div class="work-line pending" id="work-${i}"><span class="indicator">${i+1}</span>${x}</div>`).join('')}<p class="demo-note">Demo analysis · no live website crawling</p></div><section class="panel" id="summary"><div class="eyebrow">Creative brief</div><div class="placeholder"></div><div class="placeholder" style="width:70%"></div><p class="muted">Connecting your product, audience, and ambition…</p></section></div>`,1);if(!project.brief){for(let i=0;i<6;i++){if(run!==analysisRun||!$('#work-'+i))return;$('#work-'+i).className='work-line running';await new Promise(r=>setTimeout(r,450));if(!$('#work-'+i))return;$('#work-'+i).className='work-line';$('#work-'+i+' .indicator').textContent='✓'}project.brief=await analyzeBrief(project);save()}if(run!==analysisRun||!$('#summary'))return;document.querySelectorAll('.work-line').forEach(x=>{x.className='work-line';x.querySelector('.indicator').textContent='✓'});$('#summary').innerHTML=`<div class="eyebrow">创作需求</div><h2>Here’s what we heard.</h2>${Object.entries(project.brief).map(([k,v])=>`<div class="summary-item"><div class="label">${esc(k)}</div><p>${esc(v)}</p></div>`).join('')}<div class="row"><button id="edit">Edit Brief</button><button class="primary" id="generate">Generate Creative 创意方向 →</button></div>`;$('#edit').onclick=()=>go('/project/new');$('#generate').onclick=async()=>{project.creativeDirections=await createDirections(project);save();go(path('directions'))}}
function moodboard(d){return `<div class="moodboard"><img src="${d.image}" alt="${esc(d.visualDirection)}"><img src="${d.image}" alt="视觉参考的细节裁切"><img src="${d.image}" alt="视觉参考的色调裁切"></div>`}
function directions(){if(!project.creativeDirections){go(path('analysis'));return}selected=project.selectedDirection||null;shell(title('03 / Creative exploration','Three ways to tell your story.','Different points of view. One shared ambition. Choose the direction that feels like your brand.',`<button id="brief-back">↖ View brief</button>`)+`<div class="agent-note"><span class="spark">✳</span><div><strong>One opportunity, three perspectives.</strong> ${esc(project.brief?.opportunity||'Explore a lifestyle story, a design-led statement, or a bolder expression.')}<br><span class="muted">Each direction connects a concept, a visual language, and a message.</span></div></div><div class="grid">${project.creativeDirections.map((d,i)=>`<article class="direction ${selected===d.id?'selected':''}" data-card="${d.id}">${moodboard(d)}<div class="card-body"><div class="index">DIRECTION 0${i+1} <span style="float:right">${['The everyday escape','The considered object','The bold departure'][i]}</span></div><h2>${esc(d.name)}</h2><p class="concept">${esc(d.concept)}</p><div class="label">视觉语言</div><p class="detail">${esc(d.visualDirection)}</p><div class="swatches">${d.palette.map(c=>`<i style="--swatch:${c}"></i>`).join('')}</div><div class="label">核心文案</div><p class="quote">“${esc(d.keyMessage)}”</p><div class="chips">${d.mood.map(m=>`<span class="chip">${esc(m)}</span>`).join('')}</div><div class="card-actions"><button data-select="${d.id}" class="${selected===d.id?'lime':''}">${selected===d.id?'✓ Selected':'Select Direction'}</button><button data-refine="${d.id}">Refine ↗</button></div>${d.feedback?`<p class="demo-note">Refined: ${esc(d.feedback)}</p>`:''}</div></article>`).join('')}</div><div class="bottom-bar"><p id="selection-note">${selected?'Your direction is selected. Let’s make it a campaign.':'You bring the judgment. We’ll handle the creative development.'}</p><button class="primary" id="develop" ${selected?'':'disabled'}>Develop This Direction →</button></div><p class="demo-note">Demo directions · curated imagery with detail crops. Refinement updates the creative brief using local rules.</p>`,2);$('#brief-back').onclick=()=>go(path('analysis'));document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{if(project.selectedDirection!==b.dataset.select)project.assets=[];project.selectedDirection=b.dataset.select;save();directions()});document.querySelectorAll('[data-refine]').forEach(b=>b.onclick=()=>refineDialog(b.dataset.refine));$('#develop').onclick=async()=>{project.assets=[];busy=true;save();go(path('campaign'));await new Promise(r=>setTimeout(r,1400));project.assets=await generateCampaign(project);busy=false;save();if(location.pathname.endsWith('/campaign'))campaign()}}
function refineDialog(id){const d=project.creativeDirections.find(x=>x.id===id);const dlg=document.createElement('dialog');dlg.innerHTML=`<div class="eyebrow">Refine your direction</div><h2>${esc(d.name)}</h2><p class="muted">What should we keep, and what should change?</p><form><textarea required aria-label="Direction feedback" placeholder="Keep this concept, but make the visual style more premium like 方向 02."></textarea><div class="row"><button type="button" id="cancel">Cancel</button><button class="primary">Update Direction →</button></div></form><p class="demo-note">Demo: refines text and styling; does not generate new photography.</p>`;document.body.append(dlg);dlg.showModal();dlg.querySelector('#cancel').onclick=()=>dlg.close();dlg.onclose=()=>dlg.remove();dlg.querySelector('form').onsubmit=async e=>{e.preventDefault();Object.assign(d,await refineDirection(d,dlg.querySelector('textarea').value));if(project.selectedDirection===id)project.assets=[];save();dlg.close();directions()}}
function selectedD(){return project.creativeDirections?.find(x=>x.id===project.selectedDirection)}
function visual(a,v=a.versions.at(-1)){return `<div class="asset-img" style="background:${esc(v.background||'#e5e7df')};aspect-ratio:${a.type==='社媒配图'?'1':'4/3'}"><img src="${esc(v.image)}" alt="${esc(a.type)} · ${esc(project.brand)}" style="filter:${esc(v.filter||'none')};transform:scale(${v.scale||1});object-position:${v.position||'center'};${v.background?'mix-blend-mode:multiply;':''}">${v.text?`<div class="asset-copy"><small>${esc(project.brand)}</small>${esc(v.text)}</div>`:''}</div>`}
function campaign(){if(!busy&&!project.assets?.length){go(path('directions'));return}const d=selectedD();if(!d){go(path('directions'));return}shell(title('04 / Your campaign',`${esc(project.brand)} — ${esc(d.name)}`,busy?'Developing one connected visual story.':'A shared idea. Three expressions. Ready for your creative judgment.',`<button id="directions-back">↖ 创意方向</button>`)+`<div class="direction-strip"><div><div class="label">Selected creative direction</div><h3>${esc(d.name)}</h3></div><div><div class="label">Core message</div><p>${esc(d.keyMessage)}</p></div><div><div class="label">Mood</div><p>${esc(d.mood.join(' / '))}</p></div></div>${busy?`<div class="busy" role="status"><span class="spark">✳</span><h2>Building your campaign.</h2><p class="lead" style="margin:15px auto">Applying the same palette, message, and visual language across your hero, product, and social assets.</p></div>`:`<div class="grid">${(project.assets||[]).map(a=>`<article class="asset-card"><button data-asset="${a.id}" aria-label="Review ${esc(a.type)}">${visual(a)}</button><div class="asset-info"><div><h3>${esc(a.type)}</h3><p>${esc(a.format)} · V${a.versions.length}</p></div><button class="text" data-asset="${a.id}" aria-label="Edit ${esc(a.type)}">↗</button></div></article>`).join('')}</div><div class="agent-note"><span class="spark">✳</span><div><strong>A campaign that holds together.</strong><br>The same art direction and message connect all three assets. Open any visual to give feedback and explore a new version.</div></div><div class="bottom-bar"><p>Campaign overview · ${(project.assets||[]).length} assets</p><button class="primary" id="download">下载素材 ↓</button></div><p class="demo-note">Demo imagery: pre-generated NOMA photography; custom product uploads are composed locally. Asset edits use visual transformations, not live generative AI.</p>`}`,3);$('#directions-back').onclick=()=>go(path('directions'));document.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>go(path('asset/'+b.dataset.asset)));if($('#download'))$('#download').onclick=download}
function assetDetail(id,version){const a=project.assets?.find(x=>x.id===id);if(!a){go(path('campaign'));return}const vi=version??a.versions.length-1,v=a.versions[vi];shell(title('查看与修改',esc(a.type),`所属方向：${esc(a.context?.directionName||selectedD()?.name||'推广创作')} · ${esc(a.context?.keyMessage||selectedD()?.keyMessage||'')}`,`<button id="back-campaign">← 返回创意工作台</button>`)+`<div class="asset-layout"><div>${visual(a,v)}<div class="versions" aria-label="历史版本">${a.versions.map((_,i)=>`<button data-version="${i}" class="${i===vi?'active':''}">V${i+1}</button>`).join('')}</div><div class="history-note">${esc(v.feedback||'初始素材版本。')}<br><span class="demo-note">${esc(v.change||'已应用统一的创意方向。')}</span></div></div><div><section class="panel"><div class="eyebrow">由你来判断</div><h2>想调整哪里？</h2><p class="muted" style="font-size:14px">我们会基于当前查看的版本进行修改，并保留之前的版本，方便对比。</p><form id="feedback-form"><textarea id="feedback" required aria-label="素材修改意见" placeholder="让产品更突出…" style="margin-top:24px"></textarea><div class="suggestions">${['让产品更突出','色调更温暖一些','减少画面文字','背景换成蓝色','调整成适合社媒的构图'].map(s=>`<button type="button" data-suggestion="${s}">${s}</button>`).join('')}</div><button class="primary" id="revision-button">生成新版本 →</button></form><p class="demo-note">演示版支持产品放大、暖色调、减少文字、背景混色和社媒裁切。其他修改意见会保存，暂不改变画面。</p></section><section class="panel"><div class="label">创意方向</div><h3>${esc(a.context?.directionName||selectedD()?.name||'推广创作')}</h3><p class="muted" style="font-size:14px;margin-top:12px">${esc(a.context?.visualDirection||selectedD()?.visualDirection||'')}</p></section></div></div>`);$('#back-campaign').onclick=()=>go(path('campaign'));document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>assetDetail(id,+b.dataset.version));document.querySelectorAll('[data-suggestion]').forEach(b=>b.onclick=()=>{$('#feedback').value=b.dataset.suggestion;$('#feedback').focus()});$('#feedback-form').onsubmit=async e=>{e.preventDefault();const feedback=$('#feedback').value;$('#revision-button').disabled=true;$('#revision-button').textContent='正在调整画面…';await new Promise(r=>setTimeout(r,650));a.versions.push(await reviseAsset(v,feedback));save();assetDetail(id)}}
async function download(){const button=$('#download');button.disabled=true;button.textContent='正在准备素材…';try{for(const a of project.assets){const v=a.versions.at(-1),img=new Image();img.src=v.image;await img.decode();const canvas=document.createElement('canvas');canvas.width=a.type==='社媒配图'?1080:1600;canvas.height=a.type==='社媒配图'?1080:1200;const c=canvas.getContext('2d');c.fillStyle=v.background||'#e5e7df';c.fillRect(0,0,canvas.width,canvas.height);c.filter=v.filter||'none';const s=Math.max(canvas.width/img.width,canvas.height/img.height)*(v.scale||1);if(v.background)c.globalCompositeOperation='multiply';c.drawImage(img,(canvas.width-img.width*s)/2,(canvas.height-img.height*s)/2,img.width*s,img.height*s);c.globalCompositeOperation='source-over';c.filter='none';if(v.text){c.fillStyle='white';c.shadowColor='#0008';c.shadowBlur=18;c.font='bold 25px sans-serif';c.fillText(project.brand,canvas.width*.08,canvas.height*.76);c.font='48px sans-serif';const words=Array.from(v.text);let line='',y=canvas.height*.83;for(const word of words){if(c.measureText(line+word).width>canvas.width*.84){c.fillText(line,canvas.width*.08,y);y+=58;line=''}line+=word}c.fillText(line,canvas.width*.08,y)}const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${project.brand}-${a.id}-v${a.versions.length}.png`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}toast('PNG 素材已准备好。如浏览器提示，请允许下载多个文件。')}catch{toast('素材导出失败，请刷新页面后重试。')}finally{button.disabled=false;button.textContent='下载素材 ↓'}}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_campaign_state',description:'Read the current locally saved creative campaign and selected direction.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:(input)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object');return ({project:project?{id:project.id,brand:project.brand,product:project.product,selectedDirection:project.selectedDirection,assetCount:project.assets?.length||0}:null})}})).catch(()=>{})}catch{}}
render();
